select c.customername, c.city as customer_city, os.city as office_city, sum(od.quantityordered) as total_unit_terjual, round(sum(od.priceeach * od.quantityordered) / count(distinct o.ordernumber), 2) as avg_nilai_per_order from customers c join employees e on c.salesrepemployeenumber = e.employeenumber join offices os on e.officecode = os.officecode join orders o on c.customernumber = o.customernumber join orderdetails od on o.ordernumber = od.ordernumber where os.territory = 'EMEA' group by c.customername, c.city, os.city having count(distinct(date_part('year', o.orderdate))) > 2 and sum(od.quantityordered) > 1000 and sum(od.priceeach * od.quantityordered) / count(distinct o.ordernumber) > 10000 order by avg_nilai_per_order desc;
